define('LOGIN_USER', 'admin');
define('LOGIN_PASS', 'tbl');
define('MAX_ATTEMPTS', 5);
define('LOCKOUT_TIME', 900);

// Inisialisasi session login
if (!isset($_SESSION['login_attempts'])) $_SESSION['login_attempts'] = 0;
if (!isset($_SESSION['lockout_time'])) $_SESSION['lockout_time'] = 0;
if (!isset($_SESSION['logged_in'])) $_SESSION['logged_in'] = false;

// Proses logout
if (isset($_GET['logout'])) {
    session_destroy();
    header('Location: ' . $_SERVER['PHP_SELF']);
    exit;
}

// Proses login
$login_error = '';
if (isset($_POST['login']) && !$_SESSION['logged_in']) {
    $user = $_POST['username'] ?? '';
    $pass = $_POST['password'] ?? '';
    
    if ($_SESSION['lockout_time'] > 0 && time() < $_SESSION['lockout_time']) {
        $remaining = $_SESSION['lockout_time'] - time();
        $login_error = "🔒 TOO MANY ATTEMPTS! Try again in " . gmdate("i:s", $remaining);
    } elseif (empty($user) || empty($pass)) {
        $login_error = "⚠️ All fields are required!";
    } elseif ($user === LOGIN_USER && $pass === LOGIN_PASS) {
        $_SESSION['logged_in'] = true;
        $_SESSION['user'] = $user;
        $_SESSION['login_time'] = time();
        $_SESSION['login_attempts'] = 0;
        $_SESSION['lockout_time'] = 0;
    } else {
        $_SESSION['login_attempts']++;
        $attempts_left = MAX_ATTEMPTS - $_SESSION['login_attempts'];
        if ($_SESSION['login_attempts'] >= MAX_ATTEMPTS) {
            $_SESSION['lockout_time'] = time() + LOCKOUT_TIME;
            $login_error = "🔒 MAX ATTEMPTS REACHED! Locked for 15 minutes.";
        } else {
            $login_error = "❌ INVALID CREDENTIALS KONTOEL! Attempts left: $attempts_left";
        }
    }
}

